(function(){
"use strict";

const STORAGE_KEY="transformers-normalizing-flows-study-state-v1";
const VERSION=1;
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>Array.from(root.querySelectorAll(selector));
const esc=(value)=>String(value).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c]));
const step=(id,title,overview,pointers,caption,alt,media,convention,pages)=>({id,title,overview,pointers,caption,alt,media,convention,pages});

const topics=[
  {slug:"encoder-decoder",number:"01",short:"Encoder–Decoder",title:"Encoder–Decoder & Self-Attention",duration:"40 min",color:"#8f7cff",description:"Encoder-decoder transformers with multi-head attention.",objectives:["Encoding is parallel whilst decoding is autoregressive.","Trace Q, K and V scaled dot-product attention.","Explain position, multiple heads, residual paths, FFNs and normalization."],steps:[
    step("parallel-encoding","Parallel encoding","An encoder receives the input sequence of tokes. It encodes tokens in parallel. Unlike a recurrent NNs, Transformers do not process tokes one at a time.",["Tokens are discrete inputs.","Every token is processed by an encoder layer over a single pass.","These encoded tokens provide high-dimensional context"],"The encoder converts an input sequence into encodings to be used as context in the decoding.","Lecture slides show an encoder above with a row of five input tokens.","slides/T1/1.jpg","Parallel computation are done per layer; information still moves through successive layers.","7–14"),
    step("autoregressive-decoding","Autoregressive decoding","The decoder uses the encoder output and the tokens generated so far. It predicts one new token and adds it to the output sequence.",["Generation starts with a beginning-of-sequence (BOS) token.","Causal self-attention allows each position to use only earlier output tokens.","Generation stops when the model predicts EOS or reaches the maximum length."],"The decoder predicts one token at a time from the encoded input and the current output sequence.","Animated lecture sequence showing a decoder producing Dutch words one by one.","media/decoder.mp4","Output positions are generated in sequence, but each decoder pass still uses parallel matrix operations.","16–37"),
    step("transformer-block","The Transformer block","A Transformer encoder layer has two main parts: multi-head self-attention and a feed-forward network. Residual connections and layer normalization are used around both parts.",["Self-attention combines information from different token positions.","The feed-forward network transforms each token separately.","Stacking layers gives each token a richer context."],"A Transformer encoder stacks attention and feed-forward layers with residual connections and normalization.","Lecture diagram of a repeated Transformer encoder block.","slides/T1/3.jpg","Importance is learned by attending across tokens. The feed-forward blocks store relevant feature information.","38–40"),
    step("token-relationships","Relationships between tokens","Each token compares its query with the keys of all tokens. The resulting attention weights control how much each value contributes to the output.",["Each matrix row contains the attention weights for one query token.","A larger weight gives the corresponding value a larger contribution.","The weights depend on the input tokens and the learned projections."],"The matrix shows the attention weights between query and key positions.","Lecture matrix with tokens on both axes and green attention cells.","slides/T1/4.jpg","Attention weights affect how one head combines values.","41–47"),
    step("qkv-projections","Queries, keys and values","Self-attention maps tokens to queries, keys, and values. Queries and keys are used to produce attention scores; values contain the information that to be attended.",["Q = XW_Q, K = XW_K, and V = XW_V.","W_Q, W_K, and W_V are learned weights.","Q and K determine the attention matrix. V determines the content of the output."],"Three learned projections produce the queries, keys, and values used by attention.","Lecture slide with orange query, magenta key and green value vectors.","slides/T1/5.jpg","If X ∈ ℝ^(N×D), then Q,K ∈ ℝ^(N×d_k) and V ∈ ℝ^(N×d_v).","48–54"),
    step("scaled-dot-product","Scaled dot-product attention","Attention first computes QKᵀ. It scales these scores, applies softmax to each row, and uses the resulting weights to combine the rows of V.",["QKᵀ contains one score for each query–key pair.","Dividing by √d_k is used as regularizer to prevent the scores from growing with the key dimension.","Softmax makes each row non-negative and gives it a sum of one."],"Scaled query–key scores are combined with value vectors.","Animated lecture sequence building the scaled dot-product attention equation.","media/attention.mp4","Attention(Q,K,V) = softmax(QKᵀ/√d_k)V. Softmax is applied across each query row.","55–78"),
    step("attention-graph","Attention summary","The graph expands the attention equation into four steps: matrix multiplication, scaling, softmax, and multiplication by V.",["Q is multiplied by Kᵀ to produce attention scores.","Scaling and softmax convert the scores to attention weights.","The weights are multiplied by V to produce one output per query."],"The graph shows the operations used to compute scaled dot-product attention.","Lecture computation graph for self-attention.","slides/T1/7.jpg","K is transposed because tokens are stored as rows. Slides that store tokens as columns use a transposed form of the equation.","79–95"),
    step("positional-encoding","Positional encodings","Self-attention does not take to account the order of the tokens by default. A positional vector is added to each token embedding before the sequence enters the encoder to fix this.",["Token and position vectors have the same dimension.","Sinusoidal encodings use sine and cosine functions at different frequencies.","The changing phases help the model represent absolute and relative positions."],"Positional encodings add sequence-order information to the token embeddings.","Animated lecture sequence introducing sinusoidal positional encoding.","media/position.mp4","Adding positional information does not change the number of tokens or the embedding dimension.","96–121"),
    step("multi-head-attention","Multi-head attention","Multi-head attention includes several attention heads in parallel. Their outputs are concatenated and projected back to the model dimension.",["Each head has its own query, key, and value projections.","Different heads can learn different attention patterns.","A final linear layer combines the head outputs."],"Several attention heads process the sequence in parallel and their outputs are combined.","Lecture diagram of multi-head attention with parallel attention branches.","slides/T1/9.jpg","Head roles are learned during training. A head is not assigned a specific meaning in advance.","122–133"),
    step("residual-ffn-norm","Residuals, FFNs and normalization","Residual connections propagate embeddings across layers. Feed-forward blocks (or often named networks) learn general pattern and features over each dimension.",["Residual connections require equal input and output shapes.","The same feed-forward network is applied to every token position.","Layer normalization uses the features of one token, not the other tokens in the sequence."],"Each encoder layer combines attention and feed-forward networks with residual connections and layer normalization.","Lecture slide discussing Transformers and normalization.","slides/T1/10.jpg","Layer normalization and tanh are different operations. One cannot replace the other without changing the model.","134–141")
  ]},
  {slug:"vit",number:"02",short:"Vision Transformer",title:"Vision Transformer",duration:"20 min",color:"#20d8c7",description:"Tokenize images over patches, add CLS token and attend over all input tokens in parallel.",objectives:["Compute the number of non-overlapping image patches.","Explain patch projection, CLS and positional embeddings.","Trace a ViT representation to a classification output."],steps:[
    step("vit-motivation","Why a Transformer for images?","A Vision Transformer first converts an image into a sequence of patches that are the embedded.",["The image must be split into visual tokens.","The encoder is same principle architecture as the one for text tokens.","Patch size controls the number of tokens and their spatial detail."],"Vision Transformer treats image classification as sequence processing over image patches.","Title page of the Vision Transformer research paper.","slides/T2/1.jpg","ViTs patchify images which are then tokenized.","142–146"),
    step("image-patching","Image patching","An image of size H×W×C is split into non-overlapping patches of size P×P×C. Each patch becomes one visual token.",["The number of patches is N = (H/P)(W/P), assuming P divides H and W.","Larger patches give fewer tokens but less spatial detail.","Each flattened patch contains P²C values."],"The image is divided into a grid, with one visual token for each patch.","Lecture slide showing a row of blue patch tokens.","slides/T2/2.jpg","N counts the patch tokens only.","147–151"),
    step("patch-projection","Patch projection","Each patch is flattened and embedded to a D-dimensional vector. The same learned projection is used for every patch.",["A P×P×C patch becomes a vector with P²C values.","One shared matrix projects all patch vectors.","The output contains N patch embeddings of dimension D."],"A learned linear projection converts each image patch into a Transformer embedding.","Lecture diagram labeled LINEAR PROJECTION above patch tokens.","slides/T2/3.jpg","Without the batch dimension, the patch matrix is X_patch ∈ ℝ^(N×D).","152–153"),
    step("cls-token","The CLS token","A learned CLS token is placed before the patch tokens. After the encoder, its final representation is used for image classification.",["CLS is a learned vector, not an image patch.","It attends to all patch tokens in every encoder layer.","Essentially CLS fuses all features over each layer."],"The CLS token is added at the start of the sequence and provides the representation used for classification.","Lecture slide identifying the first sequence element as the CLS token.","slides/T2/4.jpg","The encoder input has (H/P)(W/P) patch tokens and one CLS token.","154–158"),
    step("vit-position","Positional embeddings","Patch embeddings contain image content but not patch location. ViT adds a positional embedding to the CLS token and every patch token.",["Each sequence position has one D-dimensional position vector.","The sequence order follows the order used to flatten the image grid.","The original ViT learns these position vectors during training."],"Position embeddings tell the encoder where the CLS and patch tokens occur in the sequence.","Lecture diagram showing orange positional embeddings above visual tokens.","slides/T2/5.jpg","The position matrix has N+1 rows: one for CLS and one for each patch.","159"),
    step("vit-output","Encoder and classification output","The token and position embeddings pass through the Transformer encoder. A classification head maps the final CLS representation to class scores.",["Each encoder layer contains attention and a feed-forward network.","Patch tokens exchange information with the CLS token throughout the encoder.","The output layer converts CLS from D features to one score per class."],"ViT builds patch tokens, adds CLS and position, encodes the sequence, and predicts the image class.","Animated lecture sequence assembling a Vision Transformer input and encoder.","media/vit.mp4","CLS is commonly used for classification. Dense tasks can instead use the final patch-token representations.","160–161")
  ]},
  {slug:"vision-language-autoregression",number:"03",short:"Vision–Language",title:"Vision–Language & Autoregressive Generation",duration:"30 min",color:"#ff9e63",description:"Connect modality tokenization to next-token likelihoods, and causal decoding.",objectives:["Relate modality-specific encoders to a shared token context.","Factor a sequence likelihood with causal conditioning.","Explain sampling and autoregressive generation across modalities."],steps:[
    step("modality-tokenization","When vision meets language","Vision-language models combine two modalities. This is done with two separate encoders: one for images and another for text.",["A text encoder produces text tokens. An image encoder produces visual tokens.","Projection layers map both types of tokens to compatible dimensions.","Pulling embeddings from each modality together is done with a contrastive objective"],"Vision and language are combined after each input has been converted to a sequence of vectors.","Lecture title slide reading When Vision met Language.","slides/T3/1.jpg","Images and text use different input encoders. Their vector representations are learned to be embedded close to each-other.","162–170"),
    step("llm-context","Large language models","A large language model predicts each token from the tokens that come before it. The model can use only the tokens inside its context window.",["A tokenizer maps text to a finite vocabulary.","The model produces one probability for each possible next token."],"An LLM assigns probabilities to token sequences by predicting the next token from the current context.","Lecture slide with large LLM letters.","slides/T3/2.jpg","LLMs are large Transformers that attend over text tokens. The tokenizer converts tokens to text from a dictionary.","171"),
    step("vlm-context","Vision-language models","A vision-language model uses both images and text. Encoded embedding for an image/video can be added to the input sequence.",["The vision encoder converts the image into visual features.","Text encoder embed text in a similar fashion.","Output sequences are based on multi-modal context."],"A VLM combines visual features with text tokens.","Lecture slide with green V and white LM letters.","slides/T3/3.jpg","A VLMs use image-text embedding spaces to predict the next token - extending context across modalities.","172–183"),
    step("vocabulary-encoding","Vocabularies and token encodings","An autoregressive model predicts the index of a token from a finite vocabulary. You can think of this index as a corresponding word for a vocabulary.",["The predicted token corresponds to the index of the next token.","The embedding matrix maps each token index to a dense vector."],"The vocabulary lists the symbols that the model can predict at each sequence position.","Lecture equation showing a finite set of discrete symbols.","slides/T3/5.jpg","Vocabulary size is the number of possible output tokens. Context length is the number of input tokens the model can use.","184–195"),
    step("likelihood-factorization","Sequence likelihood","We can write the probability of a sequence of words as a product of next-token probabilities. Each term uses the tokens before the current prediction.",["p(x_t | x_<t) predicts token x_t from the earlier tokens x_<t.","The objective is to match the product to the target token","In training the objective evaluates all positions in parallel."],"The probability of a sequence is the product of its causal next-token probabilities.","Lecture equation for autoregressive sequence likelihood.","slides/T3/6.jpg","p(x) = ∏_t p(x_t | x_<t). The model autorgressively predicts the next token given both the context and what it has been generated up to now.","196–198"),
    step("causal-decoder","Causal decoder operation","A causal mask blocks attention to future tokens. During generation, the decoder predicts one token, adds it to the sequence, and predicts the next token.",["The current sequence is the context for the next prediction.","The output logits are converted to probabilities over the vocabulary.","Each new token changes the context for later predictions."],"The decoder grows the sequence one token at a time using only the tokens already available.","Animated lecture sequence of token-by-token decoder generation.","media/autoregressive.mp4","Training can process all positions in parallel with a causal mask. Generation must produce positions in order.","199–212"),
    step("next-token-sampling","Next-token sampling","The model gives a probability to every possible next token. A decoding rule either chooses the most likely token or samples from this distribution.",["Temperature controls how concentrated the token probabilities are.","Top-k keeps the k most likely tokens. Nucleus sampling keeps the smallest set above a probability threshold.","The chosen token changes every later prediction."],"At each step, the decoder selects one token from the predicted next-token distribution.","Lecture slide pairing the likelihood equation with autoregressive generation.","slides/T3/7.jpg","The decoding rule changes how a token is selected. It does not change the autoregressive probability model.","213–224"),
    step("beyond-text","Autoregression beyond text","Autoregressive models can generate images, audio, or actions if these data are written as an ordered sequence of tokens.",["A tokenizer defines what one token represents.","An ordering defines which tokens count as the earlier context.","The same chain rule applies after the tokens and their order are fixed."],"Autoregressive generation applies to any data that can be represented as an ordered token sequence.","Lecture slide asking autoregressive generation beyond text.","slides/T3/8.jpg","The chain rule is the same across modalities. The token representation and sequence order are design choices.","225")
  ]},
  {slug:"normalizing-flows",number:"04",short:"Bijections",title:"Normalizing Flows: Bijections & Transport",duration:"25 min",color:"#f3cf55",description:"Build an invertible transport between a simple density and complex data through reversible maps.",objectives:["Distinguish injective, surjective and bijective maps.","Keep density evaluation and generation directions consistent.","Reverse a composition in the correct order."],steps:[
    step("source-target","Source and target distributions","A normalizing flow connects a simple latent distribution to a more complex data distribution. The map is invertible, so it supports both generation and density evaluation.",["The latent distribution p_Z is easy to sample and evaluate.","The model learns a distribution p_X for the data.","Each data point is paired with one latent point."],"An invertible map connects a simple latent distribution to the data distribution.","Lecture collage labeling source distribution, transport model and target distribution.","slides/T4/1.jpg","This studio uses z = f(x) for density evaluation and x = f⁻¹(z) for generation.","226–237"),
    step("forward-inverse","Forward and inverse maps","The forward map f sends a data point x to a latent point z. The inverse map f⁻¹ sends z back to x.",["Density evaluation uses z = f(x).","Generation samples z and computes x = f⁻¹(z).","Applying one map after the other recovers the starting point."],"The forward and inverse maps move between data space and latent space.","Animated diagram connecting white and green distributions with inverse arrows.","media/bijections.mp4","Some sources define f in the opposite direction. Always check the stated direction before using the Jacobian formula.","232–240"),
    step("injective-surjective","Injective and surjective maps","An injective map never sends two different inputs to the same output. A surjective map reaches every point in its output space.",["Injective: each output has at most one input.","Surjective: each output has at least one input.","Bijective: each output has exactly one input."],"A surjective map reaches every target point but may map several inputs to the same target.","Lecture diagram showing several source points mapping onto every target point.","slides/T4/3.jpg","These properties depend on the chosen domain and codomain.","241–252"),
    step("bijection","Why bijection matters","A bijection pairs each data point with exactly one latent point. This makes the inverse unique.",["Each x maps to one z.","Each z maps back to one x.","A differentiable bijection supports generation and exact density evaluation."],"A bijection gives a one-to-one match between data points and latent points.","Lecture diagram with one-to-one lines between source and target distributions.","slides/T4/4.jpg","Standard normalizing flows use data and latent spaces with the same dimension.","253–257"),
    step("invertible-networks","How can a neural network be invertible?","A general neural network may be hard to invert and may have an expensive Jacobian determinant. Flow models use special layers that make both calculations efficient.",["Each layer has a direct inverse.","Several simple layers are composed to build a flexible model.","Each layer also has a cheap log-determinant."],"Flow layers are designed for efficient inversion and density evaluation.","Lecture slide asking How to do this with a NN over source and target samples.","slides/T4/5.jpg","Invertibility alone is not enough. Likelihood training also needs an efficient Jacobian determinant.","258–260"),
    step("composition","Composition of transformations","A normalizing flow combines several simple invertible maps. Each layer transforms the output of the layer before it.",["A composition of bijections is also a bijection.","For z = f_N∘⋯∘f_1(x), f_1 is applied first.","The total log-determinant is the sum of the layer log-determinants."],"A deep flow is a sequence of simple invertible transformations.","Lecture equation showing a composition of invertible functions.","slides/T4/6.jpg","Each layer determinant is evaluated at the input received by that layer.","261–267"),
    step("reverse-composition","Reversing a composition","To invert a sequence of functions, apply their inverses in the opposite order. Generation therefore runs through the flow layers backward.",["Undo the last forward layer first.","Continue backward until the first layer is inverted.","Keeping the original order does not give the inverse."],"Generation applies the inverse flow layers in reverse order.","Lecture diagram of three densities connected by inverse transformations.","slides/T4/7.jpg","If f = f_N∘⋯∘f_1, then f⁻¹ = f_1⁻¹∘⋯∘f_N⁻¹. The first inverse applied is f_N⁻¹.","268–274")
  ]},
  {slug:"flow-architectures",number:"05",short:"Flow likelihood",title:"Flow Architectures & Likelihood",duration:"40 min",color:"#ff6f91",description:"Open the coupling layer, derive its inverse and determinant, then connect geometry to exact likelihood.",objectives:["Derive affine coupling forward, inverse and log-determinant expressions.","Connect local Jacobian volume change to density change.","Explain exact maximum likelihood and latent attribute editing."],steps:[
    step("coupling-motivation","Coupling-layer architecture","An affine coupling layer imposes a triangular dependency structure on the transformation. This restriction yields an explicit inverse and a triangular Jacobian whose determinant can be computed in linear time with respect to dimensionality.",["The input variables are divided into two complementary partitions.","One partition is copied and used to parameterize an affine transformation of the other partition.","Permuting or alternating the partitions across layers allows every dimension to be transformed."],"The coupling-layer design restricts dependencies so that inversion and Jacobian-determinant evaluation remain tractable.","Lecture title slide for coupling layer architecture.","slides/T5/1.jpg","The scale and translation networks need not be invertible because their conditioning input is copied unchanged and is therefore available in both directions.","275–280"),
    step("unchanged-partition","The unchanged partition","The first input partition is copied directly to the corresponding output partition. During inversion, this copied value is immediately available and can be used to reconstruct the parameters of the transformation applied to the second partition.",["The identity branch is defined by z_a = x_a.","Because x_a = z_a, the conditioning variables are known before x_b is reconstructed.","Only one partition is transformed within an individual coupling layer."],"The first partition follows an identity map and supplies the conditioning variables required for inversion.","Lecture diagram stating that the first part of x remains the same.","slides/T5/2.jpg","The unchanged partition limits a single layer, not the complete flow; later layers change the partition assignment so all components can be transformed.","281–284"),
    step("affine-partition","Scale and translation networks","The copied partition x_a is passed to neural networks that produce elementwise log-scale s(x_a) and translation t(x_a) parameters. These parameters define an affine transformation of x_b.",["The factor exp(s(x_a)) multiplies x_b elementwise and is strictly positive for finite s.","The vector t(x_a) translates the scaled variables elementwise.","The conditioning networks may be expressive because their outputs can be recomputed from z_a during inversion."],"Neural networks conditioned on the unchanged partition parameterize the scale and translation of the complementary partition.","Lecture coupling diagram with s and t branches.","slides/T5/3.jpg","Using exp(s) produces nonzero diagonal scaling factors, which makes the affine transformation invertible for every finite network output.","285–290"),
    step("alternating-layers","Alternating coupling layers","A single coupling layer leaves one partition unchanged, so multiple layers use complementary masks or invertible permutations between transformations. Their composition allows dependencies and transformations to propagate across all dimensions.",["A mask specifies which components form the identity branch in a given layer.","Alternating masks or permuting coordinates changes which variables condition and which variables are transformed.","Composing the resulting bijections increases expressivity while preserving an exact inverse."],"Successive coupling layers change the partition assignment so dimensions copied by one layer can be transformed by another.","Lecture diagram of two alternating affine coupling layers.","slides/T5/4.jpg","A fixed permutation is itself invertible and has |det J| = 1, so it contributes zero to the log absolute determinant.","291–294"),
    step("forward-inverse-equations","Forward and inverse equations","Affine coupling is explicitly invertible because the identity branch reveals the conditioning variables. The same scale and translation values are recomputed from z_a = x_a and used to undo the affine transformation of the second partition.",["Forward identity branch: z_a = x_a.","Forward affine branch: z_b = x_b ⊙ exp(s(x_a)) + t(x_a).","Inverse affine branch: x_b = (z_b − t(z_a)) ⊙ exp(−s(z_a))."],"The affine coupling construction exposes the copied partition, conditional parameters, forward transformation, and closed-form inverse.","Animated lecture sequence building an affine coupling layer and its inverse equations.","media/coupling.mp4","For z = f(x), log|det J_f(x)| = Σ_j s_j(x_a); the inverse transformation has the negative log absolute determinant at the corresponding point.","295–301"),
    step("mass-preservation","Mass is preserved","An invertible transformation assigns equal probability to corresponding regions in the data and latent spaces. When the transformation expands local volume, density decreases by the reciprocal volume factor; when it contracts volume, density increases.",["Probability mass is the integral of a density over a measurable region.","The image of a region under a bijection contains the same probability mass as the original region.","Density changes because the coordinate volume associated with that fixed mass changes."],"The stretching analogy illustrates how fixed mass occupies different volumes under an invertible transformation.","Lecture image of hands stretching dough with the caption Mass is neither created nor destroyed.","slides/T5/6.jpg","The absolute Jacobian determinant gives the local volume-scaling factor that relates the two densities through change of variables.","302–318"),
    step("jacobian-geometry","Jacobian geometry","For a differentiable map f, the Jacobian J_f(x) is the linear approximation that maps an infinitesimal displacement near x to its displacement near f(x). Its determinant gives the signed local volume-scaling factor.",["The entry (J_f)_{ij} = ∂f_i/∂x_j measures how output component i changes with input component j.","The magnitude |det J_f| gives the local scaling of length in one dimension, area in two dimensions, and volume in higher dimensions.","A zero determinant indicates a locally singular map and is incompatible with a differentiable local inverse."],"The Jacobian relates local displacement vectors before and after transformation, and its determinant quantifies the associated volume change.","Animated lecture sequence deriving a two-dimensional Jacobian determinant from local volume change.","media/jacobian.mp4","For z = f(x), J_f(x) = ∂z/∂x and |det J_f(x)| measures latent-space volume per unit data-space volume at x.","319–338"),
    step("change-of-variables","Change of variables","Under the data-to-latent bijection z = f(x), the data density equals the base density evaluated at f(x), multiplied by the absolute determinant of the forward Jacobian. This factor compensates exactly for local volume distortion.",["Transform the observation to its latent coordinate z = f(x).","Evaluate the base density p_Z at the transformed point z.","Multiply by |det ∂f/∂x|, or add its logarithm when computing log density."],"The change-of-variables formula combines the base density with the local volume correction of the data-to-latent map.","Lecture equation connecting px, pz and the determinant of J.","slides/T5/8.jpg","p_X(x) = p_Z(f(x))|det ∂f(x)/∂x|, hence log p_X(x) = log p_Z(f(x)) + log|det ∂f(x)/∂x|.","339–344"),
    step("maximum-likelihood","Exact likelihood optimization","When f, the base density, and the forward log absolute Jacobian determinant are tractable, the model assigns an exactly evaluable density to each observation. Its parameters can therefore be optimized directly by maximum likelihood.",["Standard normalizing flows do not require a variational lower bound to evaluate their model likelihood.","The base-density term measures how probable the transformed observation is under p_Z.","The log-determinant term accounts for the density change induced by local expansion or contraction."],"Flow log likelihood is the sum of the transformed base log density and the layerwise log-volume corrections.","Lecture slide with the logarithmic change-of-variables equation.","slides/T5/9.jpg","With z = f(x), maximize log p_Z(z) + Σ_l log|det J_{f_l}|, evaluating each layer Jacobian at the appropriate intermediate variable.","345–350"),
    step("latent-editing","Glow, CelebA and Flow++","Image-based flows such as Glow demonstrate exact likelihood evaluation, sampling, and manipulation in an invertible latent space. Attribute-associated directions estimated from labeled CelebA representations can modify decoded samples, while Flow++ improves the likelihood model through more expressive coupling transformations and variational dequantization.",["CelebA contains more than 200,000 face images annotated with 40 binary attributes.","An attribute direction can be estimated, for example, from the difference between mean latent representations of two labeled groups.","Moving a latent representation along that direction and applying f⁻¹ produces a corresponding empirical change in the generated image."],"Labeled latent representations can be used to estimate directions associated with facial attributes such as smiling.","Lecture diagram with red smiling and blue not-smiling latent clusters.","slides/T5/10.jpg","An attribute-associated latent direction represents correlation in the learned model; it need not isolate a single factor or identify a causal intervention.","351–365")
  ]}
];

const quizzes={
  "encoder-decoder/autoregressive-decoding":{id:"q1",q:"At inference, a model translates a 12-token source after generating four target tokens. Which computation claim is correct?",options:["The encoder must wait for target token five before it can finish the source representation.","Decoder weights are updated after each generated token, which forces sequential generation.","All source positions can be encoded together within a layer, but target token five must wait for the four-token output prefix.","Each attention head must finish before the next head can run."],answer:2,why:"The complete source is available to the encoder, while a not-yet-generated target token cannot be part of the decoder prefix.",wrong:"Separate model execution from parameter learning: ask which tokens already exist when each representation is computed."},
  "encoder-decoder/qkv-projections":{id:"q2",q:"A developer changes only W_V while keeping W_Q, W_K, and the input fixed. What can remain unchanged?",options:["The attention output vectors, because values do not affect the result.","The attention-weight matrix can remain identical even though the mixed output content changes.","The query–key scores must change, but the output must stay fixed.","Both the weights and outputs must remain identical."],answer:1,why:"QKᵀ fixes the attention weights. Changing V changes the information combined by those weights without changing the weights themselves.",wrong:"Trace the two stages separately: Q and K choose mixing coefficients; V supplies what is mixed."},
  "encoder-decoder/scaled-dot-product":{id:"q3",q:"As d_k grows, unscaled query–key logits become large and row-softmax saturates. Which intervention directly addresses the cause?",options:["Apply softmax to V before computing QKᵀ.","Normalize once over the entire score matrix.","Divide the final attention output by the sequence length.","Divide QKᵀ by √d_k before applying row-wise softmax."],answer:3,why:"The √d_k factor controls score variance before each query row is converted into a distribution over keys.",wrong:"The problem occurs in the compatibility logits, before values are mixed; correct it at that point."},
  "encoder-decoder/multi-head-attention":{id:"q4",q:"Two tokens must track syntax while also linking a distant entity. What does multi-head attention add beyond one head of the same total width?",options:["Independent projections and softmax patterns that can represent both relations in parallel.","A guarantee that one named head learns syntax and another learns entities.","An implicit replacement for positional information.","Sequential execution of one relation after the other."],answer:0,why:"Heads learn distinct projection subspaces and attention distributions, although no particular semantic role is guaranteed.",wrong:"Focus on the extra learned projections and attention distributions, not on predefined human-readable roles."},
  "vit/image-patching":{id:"q5",q:"A 320×192 RGB image is split into 16×16 patches and one CLS token is prepended. What enters the encoder, ignoring batch size?",options:["240 tokens, because CLS replaces one patch.","321 tokens, one for each image row plus CLS.","241 tokens, represented by a 241×D embedding matrix.","3,072 tokens, one for each patch value."],answer:2,why:"The patch grid is (320/16)×(192/16)=20×12=240; prepending CLS gives 241 D-dimensional tokens.",wrong:"Compute the two-dimensional patch grid first, then add non-patch tokens such as CLS."},
  "vit/cls-token":{id:"q6",q:"A ViT removes CLS but keeps all final patch-token states. What is the smallest valid redesign for image classification?",options:["Feed only the first image patch to the unchanged CLS classifier.","Pool the final patch states and train the classification head on that pooled representation.","Insert the ground-truth one-hot label as the missing token.","Average the raw pixels after the Transformer and skip learned classification."],answer:1,why:"CLS is a readout mechanism, not a requirement of self-attention. Pooling contextualized patch states supplies another sequence-level representation.",wrong:"Ask which remaining representations already contain contextualized image information and how they can become one vector."},
  "vision-language-autoregression/modality-tokenization":{id:"q7",q:"An image encoder outputs 1,024-D features, text embeddings are 768-D, and the fusion Transformer expects D=512. What must the model do?",options:["Pad both raw modalities to 1,024 dimensions and attend before tokenization.","Force the image and text encoders to share identical weights.","Convert every image feature into a vocabulary index from the text tokenizer.","Project each modality's tokens into 512-D while retaining the token ordering and modality context needed by the fusion model."],answer:3,why:"Modality-specific encoders may differ, but their output tokens need compatible model dimensions before joint Transformer processing.",wrong:"Compatible fusion representations do not require identical raw inputs or identical encoders; follow the token dimensions into the shared model."},
  "vision-language-autoregression/likelihood-factorization":{id:"q8",q:"For the sequence (a,b,c,d), which statement correctly describes the training loss term for c?",options:["−log p(c|a,b); masked training may still evaluate the terms for several positions in one parallel pass.","−log p(c|d); the future target provides the strongest context.","−log p(a,b|c); the model reconstructs the prefix from the current token.","−log p(c); causal models cannot condition during training."],answer:0,why:"The causal factor for c uses exactly the earlier prefix (a,b). A causal mask permits parallel training evaluation without revealing future tokens.",wrong:"Write the chain rule for the sequence and isolate the factor whose predicted token is c."},
  "vision-language-autoregression/next-token-sampling":{id:"q9",q:"The same trained logits are decoded with temperature 1.5 instead of 0.5, followed by nucleus sampling. What changes?",options:["The model weights adapt online to the sampled token.","The causal likelihood factorization becomes bidirectional.","The eligible next-token distribution is generally flatter and sampling may become more diverse; later distributions change through the sampled prefix.","The vocabulary permanently loses every token outside the first nucleus."],answer:2,why:"Temperature and nucleus sampling change the decoding distribution, not the learned weights or causal model. The sampled token then changes subsequent context.",wrong:"Distinguish the trained probability model from the temporary rule used to select one next token."},
  "normalizing-flows/bijection":{id:"q10",q:"Consider g(x)=x² from ℝ to [0,∞). Which modification makes this transport bijective?",options:["Keep the domain ℝ; surjectivity already guarantees an inverse.","Restrict the domain to [0,∞), so each target has exactly one preimage.","Change only the codomain to ℝ, keeping every real input.","Remove x=0 from the domain while keeping the rest of ℝ."],answer:1,why:"On [0,∞), squaring is both one-to-one and onto [0,∞), with inverse √z. On ℝ, x and −x collide.",wrong:"Check injectivity and surjectivity separately, including the two inputs x and −x."},
  "normalizing-flows/reverse-composition":{id:"q11",q:"Let f₁(x)=x+2, f₂(x)=3x, and f₃(x)=x−5, with z=(f₃∘f₂∘f₁)(x)=7. Which inverse trace recovers x?",options:["7→5→15→20, giving x=20.","7→9→27→22, giving x=22.","7→12→10→10/3, giving x=10/3.","7→12→4→2, giving x=2."],answer:3,why:"Undo the last forward operation first: f₃⁻¹ adds 5, f₂⁻¹ divides by 3, and f₁⁻¹ subtracts 2.",wrong:"Write the intermediate values in the forward pass, then reverse both the operation and the layer order."},
  "flow-architectures/unchanged-partition":{id:"q12",q:"In affine coupling, s and t are arbitrary neural networks and need not be invertible. Why is the complete layer still invertible?",options:["z_a=x_a exposes the conditioning input, and exp(s(x_a)) is nonzero, so the affine transform of x_b can be undone.","The scale and translation networks cancel each other for every input.","Only probability mass, not individual points, needs to be recoverable.","Alternating masks retroactively invert a non-invertible layer."],answer:0,why:"The copied partition lets the inverse recompute s and t, and a nonzero elementwise scale gives a closed-form inverse for x_b.",wrong:"Invert the coupling transformation as a whole; do not require every internal parameter network to be invertible."},
  "flow-architectures/forward-inverse-equations":{id:"q13",q:"For one affine-coupling component, s(z_a)=ln 2, t(z_a)=−1, and z_b=5. What was x_b?",options:["12, because translation is removed after doubling z_b.","2, because 5−1 is divided by 2.","3, because (5−(−1))exp(−ln 2)=6/2.","8, because the inverse repeats the forward scale."],answer:2,why:"The inverse is x_b=(z_b−t(z_a))exp(−s(z_a))=(5+1)/2=3.",wrong:"Undo translation first and then multiply by the reciprocal scale; pay attention to the sign of t."},
  "flow-architectures/jacobian-geometry":{id:"q14",q:"Near x, the Jacobian is diag(2, 0.5). What happens to a tiny square of area 0.01?",options:["Its area doubles because the first axis is scaled by 2.","It becomes a stretched rectangle but keeps area 0.01 because |det J|=2×0.5=1.","Its area halves because the second axis is scaled by 0.5.","It collapses to a line because one scale is below 1."],answer:1,why:"The two axis scalings alter shape but their product is one, so the local area-scaling factor is unchanged.",wrong:"A determinant combines scaling across all axes; multiplying the diagonal entries gives the local area factor."},
  "flow-architectures/change-of-variables":{id:"q15",q:"A three-layer flow gives log p_Z(z)=−3.4 and forward log-determinants 0.7, −0.2, and 0.1. What is log p_X(x)?",options:["−4.0, because every correction must be subtracted.","−3.4, because volume corrections cancel for bijections.","0.6, because only the Jacobian terms define likelihood.","−2.8, because −3.4+(0.7−0.2+0.1)=−2.8."],answer:3,why:"For z=f(x), log p_X(x) is the base log density plus the sum of the layerwise forward log absolute determinants.",wrong:"Keep the data-to-latent convention fixed and add the base term to every layer's log-volume correction."}
};

const topicMap=Object.fromEntries(topics.map(t=>[t.slug,t]));
const QUIZ_REVISION=2;
function shuffledIndices(count){const order=Array.from({length:count},(_,i)=>i);for(let i=order.length-1;i>0;i--){let random;if(globalThis.crypto?.getRandomValues){const value=new Uint32Array(1);globalThis.crypto.getRandomValues(value);random=value[0]}else random=Math.floor(Math.random()*2**32);const j=random%(i+1);[order[i],order[j]]=[order[j],order[i]]}return order}
function freshQuizState(q){return{revision:QUIZ_REVISION,selected:null,correct:false,attempts:0,dismissed:false,order:shuffledIndices(q.options.length)}}
function topicQuizEntries(t){return Object.entries(quizzes).filter(([key])=>key.startsWith(t.slug+"/"))}
function freshTopic(t){return{currentStep:t.steps[0].id,visited:[],notes:{},quizState:Object.fromEntries(topicQuizEntries(t).map(([,q])=>[q.id,freshQuizState(q)])),summary:""}}
function freshState(){return{version:VERSION,updatedAt:new Date().toISOString(),topics:Object.fromEntries(topics.map(t=>[t.slug,freshTopic(t)]))}}
let state=loadState();
let pendingConfirm=null;
let toastTimer=0;
let openNablaKey=null;

function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return freshState();const parsed=JSON.parse(raw);const normalized=validateState(parsed);localStorage.setItem(STORAGE_KEY,JSON.stringify(normalized));return normalized}catch(e){return freshState()}}
function saveState(){state.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));const dot=$(".save-dot");if(dot){dot.style.background="var(--good)";dot.title="Saved on this device"}}catch(e){showToast("This browser could not save locally.",true)}}
function validateState(value){
  if(!value||typeof value!=="object"||value.version!==1||!value.topics||typeof value.topics!=="object")throw new Error("Only version-1 studio backups are supported.");
  const unknown=Object.keys(value.topics).filter(k=>!topicMap[k]);if(unknown.length)throw new Error("Backup contains an unknown topic: "+unknown[0]);
  const out=freshState();
  for(const t of topics){const src=value.topics[t.slug];if(!src||typeof src!=="object")throw new Error("Backup is missing topic: "+t.slug);const ids=new Set(t.steps.map(s=>s.id));
    if(src.currentStep!=="summary"&&!ids.has(src.currentStep))throw new Error("Backup has an unknown current step in "+t.slug);
    if(!Array.isArray(src.visited)||src.visited.some(id=>!ids.has(id)))throw new Error("Backup has unknown visited steps in "+t.slug);
    if(!src.notes||typeof src.notes!=="object"||Object.keys(src.notes).some(id=>!ids.has(id))||Object.values(src.notes).some(v=>typeof v!=="string"))throw new Error("Backup has invalid notes in "+t.slug);
    const quizById=Object.fromEntries(topicQuizEntries(t).map(([,q])=>[q.id,q]));const validQuizIds=new Set(Object.keys(quizById));const qs=src.quizState||{};
    if(typeof qs!=="object"||Object.keys(qs).some(id=>!validQuizIds.has(id)))throw new Error("Backup has unknown quiz data in "+t.slug);
    const normalizedQuizState=Object.fromEntries(Object.values(quizById).map(q=>[q.id,freshQuizState(q)]));
    for(const [qid,qv] of Object.entries(qs)){const quiz=quizById[qid];const selected=qv?.selected;if(!qv||typeof qv!=="object"||(selected!==null&&selected!==undefined&&(!Number.isInteger(selected)||selected<0||selected>=quiz.options.length))||typeof qv.correct!=="boolean"||!Number.isInteger(qv.attempts)||qv.attempts<0||typeof qv.dismissed!=="boolean")throw new Error("Backup has malformed quiz data in "+t.slug);if(qv.revision!==QUIZ_REVISION)continue;const order=qv.order;const validOrder=Array.isArray(order)&&order.length===quiz.options.length&&new Set(order).size===quiz.options.length&&order.every(i=>Number.isInteger(i)&&i>=0&&i<quiz.options.length);if(!validOrder||(qv.correct&&selected!==quiz.answer))throw new Error("Backup has malformed quiz data in "+t.slug);normalizedQuizState[qid]={revision:QUIZ_REVISION,selected:selected??null,correct:qv.correct,attempts:qv.attempts,dismissed:qv.dismissed,order:[...order]}}
    if(typeof src.summary!=="string")throw new Error("Backup has an invalid summary in "+t.slug);
    out.topics[t.slug]={currentStep:src.currentStep,visited:[...new Set(src.visited)],notes:{...src.notes},quizState:normalizedQuizState,summary:src.summary};
  }
  out.updatedAt=typeof value.updatedAt==="string"?value.updatedAt:new Date().toISOString();return out;
}

function topicProgress(t){return Math.round(state.topics[t.slug].visited.length/t.steps.length*100)}
function overallProgress(){const total=topics.reduce((n,t)=>n+t.steps.length,0);const seen=topics.reduce((n,t)=>n+state.topics[t.slug].visited.length,0);return Math.round(seen/total*100)}
function completedQuizzes(t){const valid=Object.entries(quizzes).filter(([key])=>key.startsWith(t.slug+"/")).map(([,q])=>q);return valid.filter(q=>state.topics[t.slug].quizState[q.id]?.correct).length}

function headerTools(){return`<div class="header-tools"><div class="save-state"><span class="save-dot"></span>Saved locally</div><div class="overall"><strong>${overallProgress()}%</strong><div class="progress-track" aria-label="Overall progress ${overallProgress()} percent"><span style="width:${overallProgress()}%"></span></div></div><div class="menu"><button class="menu-button" type="button" aria-expanded="false">Notebook ···</button><div class="menu-pop" hidden><button type="button" data-action="export">Export JSON</button><button type="button" data-action="import">Import JSON</button><a href="./downloads/transformers-normalizing-flows-study-studio-offline.zip.part-01" download>Download offline · part 1</a><a href="./downloads/transformers-normalizing-flows-study-studio-offline.zip.part-02" download>Download offline · part 2</a><button class="danger" type="button" data-action="reset-all">Reset all progress</button></div></div></div>`}
function topicCard(t){const p=topicProgress(t);return`<a class="topic-card" style="--accent:${t.color}" href="#/topic/${t.slug}"><div class="card-top"><span class="card-number">${t.number}</span><span class="card-duration">${t.duration}</span></div><div class="card-copy"><h3>${esc(t.title)}</h3><p>${esc(t.description)}</p></div><div class="card-foot"><div class="card-progress"><div class="progress-track"><span style="width:${p}%"></span></div><small>${p?`${p}% explored`:"Ready to begin"}</small></div><span class="arrow" aria-hidden="true">↗</span></div></a>`}

function renderHome(){
  openNablaKey=null;
  document.title="Transformers & Normalizing Flows Study Studio";
  $("#app").innerHTML=`<main class="shell home"><div class="grid-haze"></div><header class="topbar"><a class="brand" href="#/" aria-label="University of Twente — Transformers and Normalizing Flows Study Studio"><img src="./brand/university-of-twente-white.png" alt="University of Twente"></a>${headerTools()}</header><section class="topics" aria-labelledby="topics-title"><h1 id="topics-title">Topics</h1><div class="topic-grid">${topics.map(topicCard).join("")}</div></section></main><input id="import-file" class="sr-only" type="file" accept="application/json,.json"><div class="toast" hidden></div><div class="modal" hidden></div>`;
  bindCommon();
}

function renderTopic(t){
  const ts=state.topics[t.slug];
  const isSummary=ts.currentStep==="summary";
  let index=t.steps.findIndex(s=>s.id===ts.currentStep);if(index<0)index=0;
  if(!isSummary&&!ts.visited.includes(t.steps[index].id)){ts.visited.push(t.steps[index].id);saveState()}
  const progress=topicProgress(t);
  document.title=`${t.title} · Study Studio`;
  $("#app").innerHTML=`<div class="lesson-shell" style="--accent:${t.color}"><header class="lesson-header"><a class="back" href="#/">← <span>All chapters</span></a><div class="lesson-name"><span>Chapter ${t.number}</span><strong>${esc(t.title)}</strong></div><div class="lesson-progress-block"><div class="lesson-progress-label"><span>Chapter progress</span><strong>${progress}%</strong></div><div class="progress-track" style="width:100%"><span style="width:${progress}%"></span></div></div></header><div class="lesson-layout">${renderRail(t,index,isSummary)}${isSummary?renderSummary(t):renderStep(t,index)}${isSummary?"":renderNotes(t,t.steps[index])}</div>${isSummary?"":renderNabla(t,t.steps[index])}</div><input id="import-file" class="sr-only" type="file" accept="application/json,.json"><div class="toast" hidden></div><div class="modal" hidden></div>`;
  bindTopic(t,index,isSummary);
}

function renderRail(t,index,isSummary){const ts=state.topics[t.slug];return`<nav class="rail" aria-label="Lesson steps"><div class="rail-head"><span>Lesson rail</span><span>${ts.visited.length}/${t.steps.length}</span></div><ol>${t.steps.map((s,i)=>`<li><button type="button" data-step="${s.id}" class="${!isSummary&&i===index?"active ":""}${ts.visited.includes(s.id)?"visited":""}" ${!isSummary&&i===index?'aria-current="step"':""}><span class="step-no">${String(i+1).padStart(2,"0")}</span><div><strong>${esc(s.title)}${quizzes[t.slug+"/"+s.id]?'<span class="quiz-chip">◆ check</span>':""}</strong><small>Slides ${s.pages}</small></div></button></li>`).join("")}<li><button type="button" data-step="summary" class="summary-step ${isSummary?"active":""}"><span class="step-no">Σ</span><div><strong>Chapter synthesis</strong><small>Your takeaways</small></div></button></li></ol></nav>`}
function mediaMarkup(s){const video=s.media.endsWith(".mp4");const reduce=matchMedia("(prefers-reduced-motion: reduce)").matches;return`<div class="media-wrap"><div class="media-frame">${video?`<video src="./${s.media}" muted playsinline controls preload="metadata" ${reduce?"":"autoplay"} aria-label="${esc(s.alt)}"></video>`:`<img src="./${s.media}" alt="${esc(s.alt)}">`}</div>${video?'<button type="button" class="skip-transition">Skip transition</button>':""}</div>`}
function renderStep(t,index){const s=t.steps[index];return`<main class="lesson-main"><div class="mobile-step">Step ${index+1} of ${t.steps.length}</div><div class="step-actions"><button type="button" data-nav="prev" ${index===0?"disabled":""}>← Previous slide</button><button type="button" class="primary" data-nav="next">${index===t.steps.length-1?"Topic summary":"Next slide"} →</button></div><figure class="media-stage ${s.media.endsWith(".mp4")?"video":"slide"}"><div class="media-top"><span>${s.media.endsWith(".mp4")?"Animation":"Keynote frame"}</span><span>Source ${s.pages}</span></div>${mediaMarkup(s)}<figcaption class="media-caption">${esc(s.caption)}</figcaption></figure><article class="step-explanation"><div class="step-heading"><p class="eyebrow">${t.number}.${String(index+1).padStart(2,"0")} · Concept</p><h1>${esc(s.title)}</h1></div><div class="learning-notes"><section><h2>Overview</h2><p>${esc(s.overview)}</p></section><section><h2>Pointers</h2><ul>${s.pointers.map(p=>`<li>${esc(p)}</li>`).join("")}</ul></section><section class="convention-note"><h2>Convention</h2><p>${esc(s.convention)}</p></section></div></article></main>`}
function renderNotes(t,s){const note=state.topics[t.slug].notes[s.id]||"";return`<aside class="notes"><div class="notes-head"><div><strong>Step notes</strong><br><span>Saved on this device</span></div><span class="note-count">${note.length} chars</span></div><textarea aria-label="Notes for ${esc(s.title)}" maxlength="12000" placeholder="Capture the idea in your own words…"></textarea><div class="prompt-chips"><span>Thinking prompts</span><button type="button" data-prompt="Why does this work? ">Why?</button><button type="button" data-prompt="Shape check: ">Shapes</button><button type="button" data-prompt="Common mistake: ">Pitfall</button></div><div class="notes-footer"><button type="button" data-action="export">Export JSON</button><button type="button" class="danger" data-action="reset-topic">Reset chapter</button></div></aside>`}
function renderSummary(t){const ts=state.topics[t.slug];const p=topicProgress(t);const qTotal=Object.keys(quizzes).filter(k=>k.startsWith(t.slug+"/")).length;return`<main class="summary"><p class="eyebrow">Chapter ${t.number} · Synthesis</p><h1>Make the chapter yours.</h1><p class="summary-intro">Write a compact explanation that connects the ideas without copying the slide language. Your synthesis is saved with the rest of this chapter.</p><div class="summary-grid"><section class="summary-editor"><div class="notes-head"><strong>Your synthesis</strong><span>${ts.summary.length} chars</span></div><textarea maxlength="16000" aria-label="Chapter synthesis" placeholder="Explain the chapter as if you were teaching it to a colleague…"></textarea></section><aside class="summary-status"><div class="summary-number"><strong>${p}%</strong><span>Chapter explored</span></div><dl><div><dt>Visual lessons</dt><dd>${ts.visited.length}/${t.steps.length}</dd></div><div><dt>Nabla checks</dt><dd>${completedQuizzes(t)}/${qTotal}</dd></div><div><dt>Notes with text</dt><dd>${Object.values(ts.notes).filter(Boolean).length}</dd></div></dl><p>A chapter reaches 100% when every visual lesson has been visited. Quiz results remain visible in your exported state.</p></aside></div><section class="recap"><ul>${t.objectives.map(o=>`<li>${esc(o)}</li>`).join("")}</ul></section><div class="summary-actions"><button type="button" data-action="export">Export notebook</button><button type="button" data-action="reset-topic">Reset chapter</button><button type="button" data-summary-nav="home">Return to chapters</button></div></main>`}

function nablaMascotMarkup(emote,color){const symbols={checkmark:'<path class="nabla-fallback-symbol" pathLength="1" d="M42 103 L78 136 L150 48"></path>',incorrect:'<path class="nabla-fallback-symbol" d="M52 51 L140 141 M140 51 L52 141"></path>',question:'<g class="nabla-fallback-symbol"><path d="M62 66 C62 37 82 22 105 22 C132 22 148 39 148 61 C148 82 132 92 119 102 C108 110 105 119 105 132"></path><circle cx="105" cy="157" r="8"></circle></g>'};return`<span class="nabla-mascot-stack loading" data-renderer="safe"><svg class="nabla-static-mascot" data-emote="${esc(emote)}" viewBox="0 0 192 192" aria-hidden="true" style="--nabla-fallback-color:${esc(color)}"><g class="nabla-fallback-base"><path class="nabla-fallback-body" d="M56 62 L136 62 L96 160 Z"></path><ellipse class="nabla-fallback-eye" cx="80" cy="51" rx="15" ry="20"></ellipse><ellipse class="nabla-fallback-eye" cx="112" cy="51" rx="15" ry="20"></ellipse><circle class="nabla-fallback-pupil" cx="80" cy="54" r="7"></circle><circle class="nabla-fallback-pupil" cx="112" cy="54" r="7"></circle></g>${symbols[emote]||""}</svg><nabla-mascot emote="${esc(emote)}" color="${esc(color)}" duration="2100"></nabla-mascot></span>`}

function renderNabla(t,s){const quiz=quizzes[t.slug+"/"+s.id],nablaKey=quiz?quiz.id:`guide:${t.slug}/${s.id}`,open=openNablaKey===nablaKey;let content,emote="reading-glasses";if(quiz){const qs=getQuizState(t,quiz);emote=qs.correct?"checkmark":qs.selected!==null&&qs.selected!==undefined?"incorrect":"question";const orderedOptions=qs.order.map(i=>({label:quiz.options[i],index:i}));const answered=qs.selected!==null&&qs.selected!==undefined;content=`<p class="nabla-eyebrow">Applied check · ${quiz.id.toUpperCase()}</p><h2>${esc(quiz.q)}</h2><p class="nabla-body">Reason from the model assumptions; choose the only conclusion that follows.</p><div class="nabla-options">${orderedOptions.map(({label,index})=>`<button type="button" data-answer="${index}" aria-pressed="${qs.selected===index}" class="${qs.selected===index?(index===quiz.answer?"correct":"incorrect"):""}" ${answered?"disabled":""}><span aria-hidden="true"></span>${esc(label)}</button>`).join("")}</div>${answered?`<div class="nabla-feedback"><p class="${qs.correct?"correct":"incorrect"}">${esc(qs.correct?quiz.why:quiz.wrong)}</p></div>${qs.correct?"":'<button type="button" class="nabla-action" data-quiz-action="retry">Try again</button>'}`:""}`}
  else content=`<p class="nabla-eyebrow">Nabla guide</p><h2>Turn the frame into a claim.</h2><p class="nabla-body">Use your notes to state what changes, what stays fixed, and which convention makes the diagram unambiguous.</p><button class="nabla-action" type="button" data-quiz-action="focus-notes">Open my notes</button>`;
  return`<aside class="nabla-guide ${open?"":"collapsed"}" style="--nabla-accent:${t.color};--accent:${t.color}" aria-label="Nabla study assistant"><section class="nabla-card" ${open?"":"hidden"}><button class="nabla-close" type="button" aria-label="Close Nabla ${quiz?"knowledge check":"guide"}">×</button>${content}</section><button class="nabla-character" type="button" aria-label="${open?"Replay":"Open"} Nabla ${quiz?"knowledge check":"guide"}" aria-expanded="${open}">${nablaMascotMarkup(emote,t.color)}</button></aside>`}

function bindCommon(){
  const menuBtn=$(".menu-button");if(menuBtn)menuBtn.addEventListener("click",()=>{const pop=$(".menu-pop");const open=pop.hidden;pop.hidden=!open;menuBtn.setAttribute("aria-expanded",String(open))});
  document.addEventListener("click",outsideMenu,{once:true});
  $$('[data-action="export"]').forEach(b=>b.addEventListener("click",exportState));
  $$('[data-action="import"]').forEach(b=>b.addEventListener("click",()=>$("#import-file").click()));
  const file=$("#import-file");if(file)file.addEventListener("change",importState);
  $$('[data-action="reset-all"]').forEach(b=>b.addEventListener("click",()=>confirmAction("Reset the entire studio?","All visits, notes, quiz attempts and summaries will be removed from this browser.",()=>{state=freshState();saveState();renderHome();showToast("Studio progress reset.")})));
}
function outsideMenu(e){const menu=$(".menu");if(menu&&!menu.contains(e.target)){const pop=$(".menu-pop");if(pop)pop.hidden=true;const btn=$(".menu-button");if(btn)btn.setAttribute("aria-expanded","false")}}
function bindTopic(t,index,isSummary){
  bindCommon();
  $$('[data-step]').forEach(b=>b.addEventListener("click",()=>goStep(t,b.dataset.step)));
  $$('[data-action="reset-topic"]').forEach(b=>b.addEventListener("click",()=>confirmAction("Reset this chapter?","Its visits, notes, quiz attempts and synthesis will be removed.",()=>{openNablaKey=null;state.topics[t.slug]=freshTopic(t);saveState();renderTopic(t);showToast("Chapter reset.")})));
  if(isSummary){const ta=$(".summary-editor textarea");ta.value=state.topics[t.slug].summary;ta.addEventListener("input",()=>{state.topics[t.slug].summary=ta.value;$(".summary-editor .notes-head span").textContent=ta.value.length+" chars";saveState()});$('[data-summary-nav="home"]').addEventListener("click",()=>location.hash="#/");return}
  const s=t.steps[index],ta=$(".notes textarea");ta.value=state.topics[t.slug].notes[s.id]||"";ta.addEventListener("input",()=>{state.topics[t.slug].notes[s.id]=ta.value;$(".note-count").textContent=ta.value.length+" chars";saveState()});
  $$('[data-prompt]').forEach(b=>b.addEventListener("click",()=>{const insert=b.dataset.prompt;const start=ta.selectionStart,end=ta.selectionEnd;ta.value=ta.value.slice(0,start)+insert+ta.value.slice(end);ta.focus();ta.selectionStart=ta.selectionEnd=start+insert.length;ta.dispatchEvent(new Event("input"))}));
  $('[data-nav="prev"]').addEventListener("click",()=>{if(index>0)goStep(t,t.steps[index-1].id)});
  $('[data-nav="next"]').addEventListener("click",()=>goStep(t,index===t.steps.length-1?"summary":t.steps[index+1].id));
  const video=$("video");if(video){const skip=$(".skip-transition");skip.addEventListener("click",()=>{video.pause();try{video.currentTime=video.duration||0}catch(e){}skip.textContent="Transition skipped";skip.disabled=true});video.addEventListener("ended",()=>{skip.textContent="Transition complete";skip.disabled=true})}
  const quiz=quizzes[t.slug+"/"+s.id],activeNablaKey=quiz?quiz.id:`guide:${t.slug}/${s.id}`,card=$(".nabla-card"),guide=$(".nabla-guide"),character=$(".nabla-character"),close=$(".nabla-close"),mascot=$("nabla-mascot",character),mascotStack=$(".nabla-mascot-stack",character);
  const showAnimatedMascot=()=>{if(!mascot||!mascotStack)return;if(mascot.dataset.nablaReady==="true"||mascot.shadowRoot?.querySelector("svg")){mascotStack.classList.replace("loading","ready");mascotStack.dataset.renderer="animated"}};
  const replayMascot=()=>{showAnimatedMascot();if(!mascotStack?.classList.contains("ready"))return;try{mascot.restart?.()}catch(error){console.error("Nabla mascot animation could not restart; the safe renderer remains available.",error)}};
  mascot?.addEventListener("nabla-ready",()=>{showAnimatedMascot();replayMascot()},{once:true});
  globalThis.customElements?.whenDefined("nabla-mascot").then(()=>requestAnimationFrame(()=>{showAnimatedMascot();replayMascot()})).catch(error=>console.error("Nabla mascot animation could not initialize; the safe renderer remains available.",error));
  const setNablaOpen=(open)=>{openNablaKey=open?activeNablaKey:null;card.hidden=!open;guide.classList.toggle("collapsed",!open);character.setAttribute("aria-expanded",String(open));character.setAttribute("aria-label",`${open?"Replay":"Open"} Nabla ${quiz?"knowledge check":"guide"}`)};
  character.addEventListener("click",()=>{if(card.hidden){setNablaOpen(true);replayMascot()}else replayMascot()});
  close.addEventListener("click",()=>{setNablaOpen(false);character.focus()});
  if(quiz){$$('[data-answer]').forEach(b=>b.addEventListener("click",()=>{const qs=getQuizState(t,quiz);qs.selected=Number(b.dataset.answer);qs.correct=qs.selected===quiz.answer;qs.attempts+=1;openNablaKey=activeNablaKey;saveState();renderTopic(t)}));const retry=$('[data-quiz-action="retry"]');if(retry)retry.addEventListener("click",()=>{const qs=getQuizState(t,quiz);qs.selected=null;openNablaKey=activeNablaKey;saveState();renderTopic(t)})}else{$('[data-quiz-action="focus-notes"]').addEventListener("click",()=>{setNablaOpen(false);ta.focus()})}
}
function getQuizState(t,q){const store=state.topics[t.slug].quizState;if(!store[q.id]||store[q.id].revision!==QUIZ_REVISION)store[q.id]=freshQuizState(q);return store[q.id]}
function goStep(t,id){openNablaKey=null;state.topics[t.slug].currentStep=id;if(id!=="summary"&&!state.topics[t.slug].visited.includes(id))state.topics[t.slug].visited.push(id);saveState();renderTopic(t);scrollTo({top:0,behavior:matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}

function exportState(){saveState();const blob=new Blob([JSON.stringify(state,null,2)],{type:"application/json"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=`transformers-normalizing-flows-notes-v1-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);showToast("Version-1 backup exported.")}
function importState(event){const file=event.target.files&&event.target.files[0];event.target.value="";if(!file)return;const reader=new FileReader();reader.onload=()=>{let candidate;try{candidate=validateState(JSON.parse(reader.result))}catch(e){showToast(e.message||"That backup is malformed. Nothing was changed.",true);return}confirmAction("Replace this notebook?","The imported version-1 backup will replace current progress, notes, quizzes and summaries.",()=>{openNablaKey=null;state=candidate;saveState();route();showToast("Backup restored.")})};reader.onerror=()=>showToast("The backup could not be read. Nothing was changed.",true);reader.readAsText(file)}
function confirmAction(title,body,onConfirm){pendingConfirm=onConfirm;let modal=$(".modal");if(!modal){modal=document.createElement("div");modal.className="modal";document.body.appendChild(modal)}modal.innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="confirm-title"><h2 id="confirm-title">${esc(title)}</h2><p>${esc(body)}</p><div class="modal-actions"><button type="button" data-confirm="cancel">Cancel</button><button type="button" class="danger" data-confirm="yes">Replace / reset</button></div></div>`;modal.hidden=false;$('[data-confirm="cancel"]',modal).addEventListener("click",()=>{modal.hidden=true;pendingConfirm=null});$('[data-confirm="yes"]',modal).addEventListener("click",()=>{const fn=pendingConfirm;modal.hidden=true;pendingConfirm=null;if(fn)fn()});$('[data-confirm="cancel"]',modal).focus()}
function showToast(message,error=false){let toast=$(".toast");if(!toast){toast=document.createElement("div");toast.className="toast";document.body.appendChild(toast)}clearTimeout(toastTimer);toast.textContent=message;toast.classList.toggle("error",error);toast.hidden=false;toastTimer=setTimeout(()=>{toast.hidden=true},3600)}
function route(){const match=location.hash.match(/^#\/topic\/([^/]+)$/);if(match&&topicMap[match[1]])renderTopic(topicMap[match[1]]);else{if(location.hash!=="#/"&&location.hash!=="")location.hash="#/";renderHome()}}
window.addEventListener("hashchange",route);route();
})();
